FUNCTION: insert
SIGNATURE: struct node* insert(struct node* node, int key)

SOURCE:
```c
// C program for the function called insert
// Contains target function implementation and dependency signatures

#include <stdio.h>
#include <stdlib.h>

struct node {
	int key;
	struct node *left, *right;
};

// Forward declarations for dependency functions
struct node* newNode(int item);

// Target function implementation
struct node* insert(struct node* node, int key)
{

	if (node == NULL)
		return newNode(key);


	if (key < node->key)
		node->left = insert(node->left, key);
	else
		node->right = insert(node->right, key);

	return node;
}

```

